        tk.Button(frm_btns, text="➕ YENİ DEPO KARTI EKLE", command=self.yeni_sekme_popup, 
                  bg="#dbeafe", fg="#1d4ed8", activebackground="#bfdbfe", activeforeground="#1e40af", **btn_style_ana).pack(side="left", padx=10)
