        def tiklileri_isle(hedef_durum):
            islem = False
            for child in tree.get_children(""):
                vals = tree.item(child)['values']
                if vals and vals[1] == "☑": 
                    self.imlec_finans.execute("UPDATE odemeler SET durum=? WHERE id=?", (hedef_durum, vals[0]))
                    islem = True
