        tk.Button(footer_frame, text="✍️ DİĞER (Manuel Yaz)", font=("Segoe UI", 10, "bold"), bg="#3b82f6", fg="white", relief="flat", cursor="hand2", pady=8, width=30, command=manuel_giris_ac).pack()
