        frm_top = tk.Frame(win, bg="#f1f5f9", pady=15, padx=20)
        frm_top.pack(side="top", fill="x")
        
        tk.Label(frm_top, text="Hangi aydan itibaren işlenecek?", bg="#f1f5f9", font=("Segoe UI", 10), fg="#64748b").pack(anchor="w")
        
