            create_grid_button(f_finans, "💰  GELİR TAKİBİ", "#dcfce7", "#166534", 1, 1, wrap_cmd(9))
            create_grid_button(f_finans, "📉  GİDER TAKİBİ", "#fef2f2", "#b91c1c", 2, 0, wrap_cmd(10))
